UPDATE user_daily_mission
SET current_count = #{currentCount},
    is_completed = #{isCompleted}
WHERE user_id = #{userId} AND mission_date = #{missionDate} AND mission_id = #{missionId}

UPDATE user_daily_mission
SET is_rewarded = #{isRewarded}
WHERE user_id = #{userId} AND mission_date = #{missionDate} AND mission_id = #{missionId}
